27→            // Мы пытаемся получить его максимально надежно через рефлексию.
28→            try {
29→                if (starlev$idField == null) {
30→                    // Ищем поле, которое может содержать ID или признак локального игрока
31→                    for (java.lang.reflect.Field field : state.getClass().getFields()) {
32→                        if ((field.getName().equals("id") || field.getName().equals("isLocalPlayer")) && 
33→                            (field.getType() == int.class || field.getType() == boolean.class)) {
34→                            field.setAccessible(true);
35→                            starlev$idField = field;
36→                            break;
37→                        }
38→                    }
